'use strict';
/**
 * 事实层聚合
 * ============================================================
 * 把三个体系的计算结果组装成【单一 JSON】，交给上层（编排层 / LLM / 前端）消费。
 *
 * 架构原则（这是被用户当面纠正过一次的，写在最前面）：
 *   排盘是确定性计算，必须留在服务端。前端只消费事实层 JSON，
 *   不参与任何历法/天文计算。把 787KB 的排盘引擎塞进浏览器是错的 ——
 *   不是因为做不到，而是因为那让"唯一事实来源"消失了，
 *   一旦前后端算法版本不一致，同一个人会得到两张不同的盘。
 *
 * 【时间基准的正确用法，容易搞错】
 *   八字 / 紫微 关心的是"当地时辰"，用 adopted（真太阳时或钟表时）。
 *   占星 关心的是"真实瞬间"，必须用 clock（钟表时）换算 UTC。
 *   真太阳时只是本地时间的另一种表达方式，它【不改变瞬间】。
 *   所以如果真太阳时跨了日，八字日柱会移动，但占星的儒略日不变 ——
 *   这是对的，不是 bug。
 */

const moment = require('./moment.js');
const baziLib = require('./bazi.js');
const ziweiLib = require('./ziwei.js');
const astroLib = require('./astro.js');
const rules = require('./rules.js');

/** 钟表时 → UTC 时刻（北京时间为 UTC+8） */
function clockToUTC(clock) {
  const ms = Date.UTC(clock.y, clock.m - 1, clock.d, clock.h, clock.mi) - 8 * 3600000;
  const t = new Date(ms);
  return {
    y: t.getUTCFullYear(), m: t.getUTCMonth() + 1, d: t.getUTCDate(),
    utHours: t.getUTCHours() + t.getUTCMinutes() / 60,
  };
}

/**
 * 用指定时间基准算一整套盘。
 * @param {object} o 原始输入
 * @param {'solar'|'clock'} basis
 */
function computeWith(o, basis) {
  const mo = moment.resolveMoment({ ...o, basis });

  const bazi = baziLib.chart({ ...o, moment: mo });
  const ziwei = ziweiLib.chart({ ...o, moment: mo });

  // 占星用真实瞬间（clock → UTC），不用真太阳时
  const ut = clockToUTC(mo.clock);
  const astro = astroLib.chart(ut.y, ut.m, ut.d, ut.utHours, mo.lonEast, mo.lat);

  const verify = rules.crossVerify({ bazi, ziwei, astro });
  return { moment: mo, bazi, ziwei, astro, verify };
}

/**
 * 基准敏感性检查。
 *
 * 为什么值得做：真太阳时与钟表时在某些出生时刻会给出不同的时柱
 * （子时前后、或经度偏离 120° 较远的地方）。这时"印证"的结论
 * 可能整体翻转。与其替用户选一个然后假装确定，
 * 不如把两套结论都算出来，把【翻转的维度】标出来。
 *
 * 这与占星层的 edge 标记是同一个思路：把不确定性传播到输出，
 * 而不是在内部悄悄消化掉。
 */
function basisSensitivity(primary, alt) {
  const flips = [];
  primary.verify.dimensions.forEach((d, i) => {
    const a = alt.verify.dimensions[i];
    if (!a) return;
    if (d.verdict !== a.verdict || (d.lean || null) !== (a.lean || null)) {
      flips.push({
        key: d.key,
        name: d.name,
        primaryVerdict: d.verdictLabel,
        primaryLean: d.lean || null,
        altVerdict: a.verdictLabel,
        altLean: a.lean || null,
      });
    }
  });
  return {
    timePillarDiffers: primary.bazi.timePillar.ambiguous,
    dayPillarDiffers: primary.bazi.timePillar.dayAmbiguous,
    flips,
    stable: flips.length === 0,
    note: primary.bazi.timePillar.ambiguous
      ? (flips.length === 0
        ? '两种时间基准给出的时柱不同，但印证结论未受影响 —— 说明该结论对时间基准不敏感，可信度更高。'
        : `两种时间基准给出的时柱不同，且导致 ${flips.length} 条维度的结论翻转。`
          + '这几条不宜作为判断依据，需要用户确认更准确的出生时刻。')
      : '两种时间基准的时柱一致，无基准敏感性。',
  };
}

/**
 * 主入口：产出完整事实层 JSON。
 *
 * @param {object} o
 *   y,m,d,h,mi      出生钟表时间（北京时间）
 *   gender          '男' | '女'
 *   city            地名（仅展示）
 *   lonEast, lat    出生地经纬度（东经/北纬为正）
 *   basis           'solar'（真太阳时，默认）| 'clock'（钟表时）
 *   sensitivity     是否做基准敏感性检查，默认 true
 */
function buildFact(o) {
  const basis = o.basis === 'clock' ? 'clock' : 'solar';
  const primary = computeWith(o, basis);

  let sensitivity = null;
  if (o.sensitivity !== false && primary.bazi.timePillar.ambiguous) {
    const alt = computeWith(o, basis === 'solar' ? 'clock' : 'solar');
    sensitivity = basisSensitivity(primary, alt);
  } else if (o.sensitivity !== false) {
    sensitivity = {
      timePillarDiffers: false, dayPillarDiffers: false, flips: [],
      stable: true,
      note: '两种时间基准的时柱一致，无基准敏感性。',
    };
  }

  const { moment: mo, bazi, ziwei, astro, verify } = primary;

  // 历法层互证 —— 两个独立库（lunar-javascript / iztro）各自把公历转成农历。
  // 注意不要拿干支去比：两个体系的月柱定义本来就不同 ——
  //   八字月柱按【节气】（立春/惊蛰…分月）
  //   紫微月柱按【农历月】（正月=寅月）
  // 实测 1950-03-07 这类日期二者必然不同，那不是谁错了。
  // 真正能互证的是农历日期本身。实测 55/55 一致。
  const crossCheck = {
    lunarDate: {
      byLunarJs: bazi.lunarText,
      byIztro: ziwei.lunarDate,
      consistent: bazi.lunarText === ziwei.lunarDate,
    },
    monthPillarConvention: {
      bazi: bazi.pillars[1].gz,
      ziwei: (ziwei.chineseDate || '').split(' ')[1] || null,
      same: bazi.pillars[1].gz === ((ziwei.chineseDate || '').split(' ')[1] || null),
      note: '八字月柱按节气分月，紫微月柱按农历月分月，二者定义不同，'
          + '不一致属正常，不代表任一实现有误。',
    },
    consistent: bazi.lunarText === ziwei.lunarDate,
    note: bazi.lunarText === ziwei.lunarDate
      ? '农历日期经两个独立库（lunar-javascript / iztro）交叉验证一致，历法层可信'
      : '⚠ 两个库给出的农历日期不一致，说明有一方历法实现有误，此盘不可信',
  };

  return {
    schema: 'mingli.fact/1',
    generatedAt: new Date().toISOString(),

    input: {
      y: mo.clock.y, m: mo.clock.m, d: mo.clock.d, h: mo.clock.h, mi: mo.clock.mi,
      gender: o.gender || '男',
      city: o.city || null,
      lonEast: mo.lonEast, lat: mo.lat,
      basis: mo.basis,
    },

    time: {
      clock: mo.clock,
      solar: mo.solar,
      adopted: mo.adopted,
      offsetMinutes: mo.offsetMinutes,
      longitudeMinutes: mo.longitudeMinutes,
      eotMinutes: mo.eotMinutes,
      dayShift: mo.dayShift,
      clockText: moment.fmt(mo.clock),
      solarText: moment.fmt(mo.solar),
      adoptedText: moment.fmt(mo.adopted),
    },

    bazi,
    ziwei,
    astro,
    verify,
    sensitivity,
    crossCheck,

    caveats: [
      '事实层（四柱、星曜、天体位置）是确定性计算，可复现、可验证。',
      '解读层（十神取象、星曜性质、元素对应）是传统约定，不是实证校准的预测模型。',
      '印证的逻辑是比较三个独立推导路径是否收敛，提升的是"相对可信度"，不是"绝对准确性"。',
      '本服务不提供改命、化解、消灾类内容，也不对健康、法律、投资作具体决策建议。',
    ],
  };
}

module.exports = { buildFact, computeWith, basisSensitivity, clockToUTC };

'use strict';
/**
 * 排盘计算服务 · HTTP 编排层
 * ============================================================
 * 架构（用户当面纠正过一次，写在这里防止再走回头路）：
 *
 *   [前端 聊天UI / 报告页]
 *          │  HTTP，只传出生信息与问题
 *          ▼
 *   [本服务 = 编排层]  ← 你在这里
 *          │  调用
 *          ▼
 *   [计算层 lib/]  确定性：历法、天文、安星、取象
 *
 *   前端【只消费事实层 JSON】，不参与任何历法/天文计算。
 *   把 787KB 排盘引擎塞进浏览器是错的：不是做不到，
 *   而是那会让"唯一事实来源"消失 —— 前后端算法版本一旦不一致，
 *   同一个人会拿到两张不同的盘。
 *
 * 零外部依赖：只用 Node 内置 http / fs。
 *   计算依赖（lunar-javascript / iztro）在 lib 层。
 */

const http = require('http');
const fs = require('fs');
const path = require('path');
const { buildFact } = require('./lib/fact.js');
const { CITIES, BY_NAME } = require('./lib/cities.js');

const PORT = process.env.PORT || 3007;
const PUBLIC_DIR = path.join(__dirname, 'public');

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'application/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
};

function sendJSON(res, code, obj) {
  const body = JSON.stringify(obj, null, 2);
  res.writeHead(code, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(body),
    'Access-Control-Allow-Origin': '*',
  });
  res.end(body);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', (c) => {
      data += c;
      if (data.length > 1e6) { reject(new Error('请求体过大')); req.destroy(); }
    });
    req.on('end', () => {
      if (!data) return resolve({});
      try { resolve(JSON.parse(data)); } catch (e) { reject(new Error('JSON 解析失败: ' + e.message)); }
    });
    req.on('error', reject);
  });
}

/** 输入校验：宁可明确报错，也不要用默认值悄悄算出一张错的盘 */
function validate(input) {
  const errs = [];
  const num = (v, name, min, max) => {
    const n = Number(v);
    if (!Number.isFinite(n)) { errs.push(`${name} 必须是数字`); return null; }
    if (n < min || n > max) { errs.push(`${name} 应在 ${min}–${max} 之间，收到 ${n}`); return null; }
    return n;
  };

  const y = num(input.y, '出生年', 1901, 2099);
  const m = num(input.m, '出生月', 1, 12);
  const d = num(input.d, '出生日', 1, 31);
  const h = num(input.h, '出生时', 0, 23);
  const mi = num(input.mi ?? 0, '出生分', 0, 59);

  if (input.gender && !['男', '女'].includes(input.gender)) errs.push('性别须为「男」或「女」');

  // 日期真实性检查（2月30日之类）
  if (y && m && d) {
    const dt = new Date(Date.UTC(y, m - 1, d));
    if (dt.getUTCMonth() + 1 !== m || dt.getUTCDate() !== d) errs.push(`${y}年${m}月没有${d}日`);
  }

  let lon = input.lonEast, lat = input.lat;
  if (input.city) {
    const c = BY_NAME[input.city];
    if (c) { lon = c.lon; lat = c.lat; }
    else errs.push(`未收录城市「${input.city}」，请改用经纬度输入`);
  }
  if (lon == null || lat == null) {
    errs.push('需要提供城市，或直接给出经纬度（lonEast / lat）');
  } else {
    const LON = num(lon, '经度', -180, 180);
    const LAT = num(lat, '纬度', -66, 66);
    lon = LON; lat = LAT;
  }

  if (input.basis && !['solar', 'clock'].includes(input.basis)) errs.push('时间基准须为 solar 或 clock');

  return {
    errors: errs,
    value: { y, m, d, h, mi, gender: input.gender || '男', city: input.city || null, lonEast: lon, lat, basis: input.basis },
  };
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const p = url.pathname;

  // ── CORS 预检 ──
  if (req.method === 'OPTIONS') {
    res.writeHead(204, {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET,POST,OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type',
    });
    return res.end();
  }

  // ── 健康检查 ──
  if (p === '/api/health') {
    return sendJSON(res, 200, {
      ok: true,
      service: 'mingli-agent 排盘计算服务',
      version: '1.0.0',
      schema: 'mingli.fact/1',
      endpoints: {
        'POST /api/chart': '排盘，返回事实层 JSON（八字 + 紫微 + 占星 + 印证）',
        'GET  /api/cities': '城市经纬度表',
        'GET  /api/dimensions': '印证所用共同维度定义',
      },
    });
  }

  // ── 城市表 ──
  if (p === '/api/cities') return sendJSON(res, 200, { cities: CITIES });

  // ── 维度定义 ──
  if (p === '/api/dimensions') {
    const rules = require('./lib/rules.js');
    return sendJSON(res, 200, { dimensions: rules.DIMENSIONS, validity: rules.VALIDITY });
  }

  // ── 排盘 ──
  if (p === '/api/chart') {
    if (req.method !== 'POST') return sendJSON(res, 405, { error: '请用 POST' });
    let body;
    try { body = await readBody(req); }
    catch (e) { return sendJSON(res, 400, { error: e.message }); }

    const { errors, value } = validate(body);
    if (errors.length) return sendJSON(res, 400, { error: '输入校验未通过', details: errors });

    try {
      const t0 = Date.now();
      const fact = buildFact(value);
      fact.meta = { computeMs: Date.now() - t0, engine: 'mingli-agent/1.0.0' };
      return sendJSON(res, 200, fact);
    } catch (e) {
      console.error('[chart] 排盘失败', e);
      return sendJSON(res, 500, { error: '排盘失败: ' + e.message });
    }
  }

  // ── 静态文件 ──
  if (req.method === 'GET') {
    let file = p === '/' ? '/index.html' : p;
    const full = path.join(PUBLIC_DIR, path.normalize(file).replace(/^(\.\.[/\\])+/, ''));
    if (!full.startsWith(PUBLIC_DIR)) { res.writeHead(403); return res.end('Forbidden'); }
    if (fs.existsSync(full) && fs.statSync(full).isFile()) {
      const ext = path.extname(full);
      res.writeHead(200, { 'Content-Type': MIME[ext] || 'application/octet-stream' });
      return fs.createReadStream(full).pipe(res);
    }
  }

  sendJSON(res, 404, { error: '未找到', path: p });
});

server.listen(PORT, '127.0.0.1', () => {
  console.log('命理师 Agent · 排盘计算服务');
  console.log('  监听 http://127.0.0.1:' + PORT);
  console.log('  排盘  POST http://127.0.0.1:' + PORT + '/api/chart');
  console.log('  城市  GET  http://127.0.0.1:' + PORT + '/api/cities');
  console.log('');
  console.log('  架构：前端只消费事实层 JSON，不做任何历法/天文计算。');
});

