```typescript
import { createHash, randomBytes, timingSafeEqual } from 'crypto';

export type ResetChannel = 'email' | 'otp';

export interface ResetTicket {
  readonly userId: string;
  readonly channel: ResetChannel;
  readonly tokenHash: string;
  readonly expiresAt: number;
  readonly usedAt: number | null;
}

export type ConsumeResult =
  | { ok: true; userId: string }
  | { ok: false; reason: 'expired' | 'mismatch' | 'reused' };

export interface ResetStore {
  save(ticket: ResetTicket): Promise<void>;
  find(userId: string): Promise<ResetTicket | null>;
  markUsed(userId: string, now: number): Promise<boolean>;
}

const TTL_MS = 15 * 60 * 1000;

function hash(token: string): Buffer {
  return createHash('sha256').update(token).digest();
}

export async function issueTicket(
  store: ResetStore,
  userId: string,
  channel: ResetChannel,
  now: number,
): Promise<{ token: string; ticket: ResetTicket }> {
  const token = randomBytes(32).toString('base64url');
  const ticket: ResetTicket = {
    userId,
    channel,
    tokenHash: hash(token).toString('hex'),
    expiresAt: now + TTL_MS,
    usedAt: null,
  };
  await store.save(ticket);
  return { token, ticket };
}

export async function consumeTicket(
  store: ResetStore,
  userId: string,
  token: string,
  now: number,
): Promise<ConsumeResult> {
  const ticket = await store.find(userId);
  if (!ticket) return { ok: false, reason: 'mismatch' };
  if (ticket.usedAt !== null) return { ok: false, reason: 'reused' };
  if (now > ticket.expiresAt) return { ok: false, reason: 'expired' };

  const expected = Buffer.from(ticket.tokenHash, 'hex');
  if (!timingSafeEqual(expected, hash(token))) {
    return { ok: false, reason: 'mismatch' };
  }
  if (!(await store.markUsed(userId, now))) {
    return { ok: false, reason: 'reused' };
  }
  return { ok: true, userId };
}
```

