```
import { randomUUID } from 'crypto';

export type ActionKind = 'chat' | 'report' | 'synastry';

export type LedgerState = 'reserved' | 'settled' | 'released';

export interface Reservation {
  readonly id: string;
  readonly userId: string;
  readonly action: ActionKind;
  readonly points: number;
  readonly idempotencyKey: string;
  readonly createdAt: number;
  state: LedgerState;
}

export interface Usage {
  readonly inputTokens: number;
  readonly outputTokens: number;
  readonly cachedTokens: number;
}

export interface PriceTable {
  readonly inputPerMillion: number;
  readonly outputPerMillion: number;
  readonly cachedPerMillion: number;
  readonly pointsPerYuan: number;
}

export interface LedgerStore {
  freeze(userId: string, points: number, key: string): Promise<boolean>;
  unfreeze(userId: string, points: number): Promise<void>;
  charge(userId: string, points: number): Promise<void>;
  save(r: Reservation): Promise<void>;
  findByKey(key: string): Promise<Reservation | null>;
}

export const PRICES: PriceTable = {
  inputPerMillion: 0.44,
  outputPerMillion: 1.32,
  cachedPerMillion: 0.014,
  pointsPerYuan: 10,
};

export function estimatePoints(kind: ActionKind): number {
  if (kind === 'report') return 30;
  if (kind === 'synastry') return 8;
  return 1;
}

export function costYuan(usage: Usage, price: PriceTable): number {
  const fresh = usage.inputTokens - usage.cachedTokens;
  const input = (fresh / 1e6) * price.inputPerMillion;
  const cached = (usage.cachedTokens / 1e6) * price.cachedPerMillion;
  const output = (usage.outputTokens / 1e6) * price.outputPerMillion;
  return input + cached + output;
}

export async function reserve(store: LedgerStore, userId: string, kind: ActionKind, key: string, now: number): Promise<Reservation | null> {
  const existing = await store.findByKey(key);
  if (existing) return existing;
  const points = estimatePoints(kind);
  if (!(await store.freeze(userId, points, key))) return null;
  const r: Reservation = { id: randomUUID(), userId, action: kind, points, idempotencyKey: key, createdAt: now, state: 'reserved' };
  await store.save(r);
  return r;
}
```

